	SELECT XQ3_XQ2_Question, 'XQ2' FROM inserted
	UNION
	SELECT XQ3_XQ2_Question, 'XQ2' FROM deleted

	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
